"""Experimental native XY deformation of an offline prepared quad pattern.

All instances use one group; reference geometry and response coefficients are
data inputs. The offline asset supplies validated dense rows, grouped by free
vertex, with a _qp_start address on each free reference vertex. This primitive
does not select patterns, create street boundaries, or project profile heights.
It must not replace a complete street solver without those qualifications.
"""
import bpy
from . import curved_corner_nodes as c
from . import boundary_quad_bridge_nodes as bridge
from .path_surface_nodes import _Nodes

NAME = 'Prochitecture Streets / Experimental quad boundary pattern v3 / Centered hierarchical sum'
MAX_VERTICES = 4096
MAX_COEFFICIENTS = 4_000_000
BLOCK_SIZE = 8
REDUCTION_LEVELS = 3


def build(*, expose_input_valid=False):
    name = NAME+(' / Recoverable placement v1' if expose_input_valid else '')
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    g = c.Graph(name)
    for key in ('Geometry', 'Pattern', 'Coefficients'): g.socket(key, 'NodeSocketGeometry')
    g.socket('Reference Deformation', 'NodeSocketBool', default=True)
    g.socket('Signed Coefficients', 'NodeSocketBool', default=False)
    for key in ('Geometry', 'Inspection Geometry'): g.socket(key, 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    if expose_input_valid: g.socket('Inputs Valid', 'NodeSocketBool', 'OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    source = inp.outputs['Geometry']; pattern = inp.outputs['Pattern']; weights = inp.outputs['Coefficients']
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0]); position = g.position()
    count = c._count(g, source); size = c._count(g, weights)
    valid = g.math('GREATER_THAN', count, 3.5)*g.math('LESS_THAN', count, MAX_VERTICES+.5)
    valid = valid*g.math('COMPARE', count, c._count(g, pattern))
    valid = valid*g.math('GREATER_THAN', size, .5)*g.math('LESS_THAN', size, MAX_COEFFICIENTS+.5)
    fixed = c.named(g, 'st_cq_fixed', 'BOOLEAN')
    pins = c._stat(g, pattern, fixed, 'Sum')
    valid = valid*g.math('COMPARE', size, pins*(count-pins))
    valid = valid*c._stat(g, source, g.math('COMPARE', fixed, c._sample(g, pattern, fixed, index, 'BOOLEAN')))
    # Compare the complete corner-index stream, not merely vertex/face counts.
    corner = g.node('GeometryNodeVertexOfCorner'); g.bind(index, corner.inputs['Corner Index'])
    sample = g.node('GeometryNodeSampleIndex'); sample.data_type = 'INT'; sample.domain = 'CORNER'; sample.clamp = False
    g.bind(pattern, sample.inputs['Geometry']); g.bind(corner.outputs['Vertex Index'], sample.inputs['Value'])
    g.bind(index, sample.inputs['Index'])
    valid = valid*c._stat(g, source, g.math('COMPARE', corner.outputs['Vertex Index'], sample.outputs['Value']), domain='CORNER')
    helper = _Nodes(g.g)
    valid = valid*g.math('COMPARE', bridge._size(helper, source, 'Face Count'), bridge._size(helper, pattern, 'Face Count'))
    valid = valid*g.math('COMPARE', bridge._size(helper, source, 'Face Corner Count'), bridge._size(helper, pattern, 'Face Corner Count'))
    pin = c.named(g, '_qp_pin', 'INT'); owner = c.named(g, '_qp_vertex', 'INT'); weight = c.named(g, '_qp_weight')
    admissible = g.math('GREATER_THAN', pin, -.5)*g.math('LESS_THAN', pin, count-.5)
    admissible = admissible*g.math('GREATER_THAN', owner, -.5)*g.math('LESS_THAN', owner, count-.5)
    positive_weight = g.math('GREATER_THAN', weight, -1e-7)*g.math('LESS_THAN', weight, 1.000001)
    bounded_weight = g.math('LESS_THAN', g.math('ABSOLUTE', weight), 4.000001)
    admissible = admissible*c.choose(g, inp.outputs['Signed Coefficients'], bounded_weight, positive_weight, 'BOOLEAN')
    admissible = admissible*c._sample(g, pattern, fixed, pin, 'BOOLEAN')
    admissible = admissible*(1.-c._sample(g, pattern, fixed, owner, 'BOOLEAN'))
    valid = valid*c._stat(g, weights, admissible)
    current = c._sample(g, source, position, pin, 'FLOAT_VECTOR')
    previous = c._sample(g, pattern, position, pin, 'FLOAT_VECTOR')
    # Center on all pins rather than an extreme first pin. High-valence
    # references otherwise sum long vectors across the whole junction width,
    # losing several float32 ULPs even with the short-block reduction below.
    x, y, _ = g.separate(position)
    source_pins = c._select(g, source, fixed); reference_pins = c._select(g, pattern, fixed)
    origin = g.xyz(c._stat(g, source_pins, x, 'Mean'), c._stat(g, source_pins, y, 'Mean'), 0.)
    old_origin = g.xyz(c._stat(g, reference_pins, x, 'Mean'), c._stat(g, reference_pins, y, 'Mean'), 0.)
    def vector(operation, a, b):
        node = g.node('ShaderNodeVectorMath'); node.operation = operation
        g.bind(a, node.inputs[0]); g.bind(b, node.inputs[1]); return node.outputs['Vector']
    local = vector('SUBTRACT', current, origin)
    previous_local = vector('SUBTRACT', previous, old_origin)
    delta = c.choose(g, inp.outputs['Reference Deformation'], vector('SUBTRACT', local, previous_local), local, 'VECTOR')
    # Three eight-term levels keep every reduction short even for the largest
    # permitted pin set. Avoid a final sequential sum over dozens of blocks.
    column = index-c._read(g, pattern, '_qp_start', owner, 'INT')
    block_index = g.math('FLOOR', column/BLOCK_SIZE)
    block = owner*(MAX_VERTICES//BLOCK_SIZE+1)+block_index
    total = g.node('GeometryNodeAccumulateField', 'Precomputed response in eight-term blocks')
    total.data_type = 'FLOAT_VECTOR'; total.domain = 'POINT'
    scale = g.node('ShaderNodeVectorMath'); scale.operation = 'SCALE'
    g.bind(delta, scale.inputs[0]); g.bind(weight, scale.inputs['Scale'])
    g.bind(scale.outputs['Vector'], total.inputs['Value']); g.bind(block, total.inputs['Group ID'])
    sums = g.node('GeometryNodeAccumulateField'); sums.data_type = 'FLOAT'; sums.domain = 'POINT'
    g.bind(weight, sums.inputs['Value']); g.bind(block, sums.inputs['Group ID'])
    absolute = g.node('GeometryNodeAccumulateField'); absolute.data_type = 'FLOAT'; absolute.domain = 'POINT'
    g.bind(g.math('ABSOLUTE', weight), absolute.inputs['Value']); g.bind(block, absolute.inputs['Group ID'])
    partial = c._store(g, c._select(g, weights, valid), '_qp_partial', total.outputs['Total'], 'FLOAT_VECTOR')
    partial = c._store(g, partial, '_qp_mass', sums.outputs['Total'])
    partial = c._store(g, partial, '_qp_l1', absolute.outputs['Total'])
    partial = c._store(g, partial, '_qp_block', block_index, 'INT')
    partial = c._select(g, partial, g.math('COMPARE', g.math('MODULO', column, BLOCK_SIZE), 0.))
    for level in range(1, REDUCTION_LEVELS):
        old_block = c.named(g, '_qp_block', 'INT')
        next_block = g.math('FLOOR', old_block/BLOCK_SIZE)
        group = owner*(MAX_VERTICES//BLOCK_SIZE+1)+next_block
        for field, kind in (('_qp_partial', 'FLOAT_VECTOR'), ('_qp_mass', 'FLOAT'), ('_qp_l1', 'FLOAT')):
            subtotal = g.node('GeometryNodeAccumulateField', 'Response reduction level '+str(level+1))
            subtotal.data_type = kind; subtotal.domain = 'POINT'
            g.bind(c.named(g, field, kind), subtotal.inputs['Value']); g.bind(group, subtotal.inputs['Group ID'])
            partial = c._store(g, partial, field, subtotal.outputs['Total'], kind)
        partial = c._select(g, partial, g.math('COMPARE', g.math('MODULO', old_block, BLOCK_SIZE), 0.))
        partial = c._store(g, partial, '_qp_block', next_block, 'INT')
    final = g.node('GeometryNodeAccumulateField', 'Combine the short response blocks'); final.data_type = 'FLOAT_VECTOR'; final.domain = 'POINT'
    g.bind(c.named(g, '_qp_partial', 'FLOAT_VECTOR'), final.inputs['Value']); g.bind(owner, final.inputs['Group ID'])
    mass = g.node('GeometryNodeAccumulateField'); mass.data_type = 'FLOAT'; mass.domain = 'POINT'
    g.bind(c.named(g, '_qp_mass'), mass.inputs['Value']); g.bind(owner, mass.inputs['Group ID'])
    l1 = g.node('GeometryNodeAccumulateField'); l1.data_type = 'FLOAT'; l1.domain = 'POINT'
    g.bind(c.named(g, '_qp_l1'), l1.inputs['Value']); g.bind(owner, l1.inputs['Group ID'])
    valid = valid*c._stat(g, partial, g.math('LESS_THAN', g.math('ABSOLUTE', c.V(g, mass.outputs['Total'])-1.), 1e-5))
    # Signed affine correction is XY-only and bounded. A sum of one alone
    # would permit arbitrarily large cancelling weights and unstable edits.
    valid = valid*c._stat(g, partial, g.math('LESS_THAN', l1.outputs['Total'], 4.0001))
    normalize = g.node('ShaderNodeVectorMath', 'Retain partition of unity after float32 row reduction'); normalize.operation = 'SCALE'
    g.bind(final.outputs['Total'], normalize.inputs[0])
    g.bind(g.math('DIVIDE', 1., g.math('MAXIMUM', mass.outputs['Total'], 1e-12)), normalize.inputs['Scale'])
    evaluated = c._store(g, c._select(g, partial, valid), '_qp_displacement', normalize.outputs['Vector'], 'FLOAT_VECTOR')
    start = c._read(g, pattern, '_qp_start', index, 'INT')/g.math('MAXIMUM', pins, 1.)*g.math('CEIL', pins/(BLOCK_SIZE**REDUCTION_LEVELS))
    owner_at_start = c._read(g, evaluated, '_qp_vertex', start, 'INT')
    address_valid = g.math('GREATER_THAN', start, -.5)*g.math('LESS_THAN', start, c._count(g, evaluated)-.5)*g.math('COMPARE', owner_at_start, index)
    valid = valid*c._stat(g, source, c.choose(g, fixed, True, address_valid, 'BOOLEAN'))
    displacement = c._read(g, evaluated, '_qp_displacement', start, 'FLOAT_VECTOR')
    base = c._sample(g, pattern, position, index, 'FLOAT_VECTOR')
    base = c.choose(g, inp.outputs['Reference Deformation'], vector('SUBTRACT', base, old_origin), g.xyz(0., 0., 0.), 'VECTOR')
    # Use vector arithmetic for the precomputed XY response; Z always comes
    # from the caller. Pinned source coordinates are copied without arithmetic.
    proposed = vector('ADD', origin, vector('ADD', base, displacement))
    x, y, _ = g.separate(proposed); z = g.separate(position)[2]
    mesh = g.setpos(source, c.choose(g, fixed, position, g.xyz(x, y, z), 'VECTOR'))
    # A recovery caller must distinguish valid coefficients/topology from a
    # folded placement. Inspection geometry alone must never bypass these
    # data checks when attempting a bounded geometric correction.
    if expose_input_valid: g.bind(valid, out.inputs['Inputs Valid'])
    valid = valid*c.V(g, bridge._mesh_good(helper, mesh.s))
    g.bind(c._select(g, mesh, valid), out.inputs['Geometry'])
    g.bind(mesh, out.inputs['Inspection Geometry']); g.bind(valid, out.inputs['Valid'])
    return g.g
